from lib import *
S = SS('c20')
steps = [
    step("镜像里放两个 128 MiB 的随机文件 big1.bin、big2.bin 和一个 1 KB 的 small.txt,三个新容器各跑一次同样的脚本。读 big1.bin 的 1 字节:0.1 ms(没有复制)。第 1 次往 big1.bin 追加 1 字节:2174.1 / 242.7 / 155.0 ms——三次差很多,最快的 155.0 ms;紧接着第 2 次、第 3 次追加只要 0.0~0.6 ms。第一次写入要等整个 128 MiB 先复制进可写层。不只是写数据才触发:对没碰过的 big2.bin 只做 chmod,也要 862.0 / 309.0 / 179.6 ms——元数据改动同样把整个文件复制上去;往 1 KB 的 small.txt 追加 1 字节只要 8.7 / 4.1 / 3.7 ms;作对比,新建并写入 128 MiB 的新文件(含 fsync)是 3744.2 / 999.6 / 935.1 ms。", t=tl(S(1)), done=lidx(S(1), '第 2 次往 big1.bin', '第 3 次往 big1.bin'), mark=lidx(S(1), '第 1 次往 big1.bin', 'big2.bin 只做 chmod'), b=bars([['读 1 字节 (ms)', 0.1, '0.1'], ['第 1 次追加 最快 (ms)', 155.0, '155.0'], ['第 1 次追加 最慢 (ms)', 2174.1, '2174.1'], ['第 2 次追加 (ms)', 0.1, '0.1']], 2174.1, done=[0, 3], mark=[1, 2]), kv=KV([['读', '0.1 ms,不复制'], ['第 1 次追加', '155.0~2174.1 ms(3 次)'], ['第 2、3 次追加', '约 0 ms']], ['第 1 次追加'])),
    step("看 upperdir:big1.bin 在里面,大小 134217731 字节(原来 134217728,追加了 3 字节);只做了 chmod 的 big2.bin 也在里面,134217728 字节——整个文件;small.txt 1025 字节;新建的 new.bin 134217728 字节;还有 python 自己写出的几个 __pycache__。整个文件被复制,而不是只复制改动的那一块。", t=tl(S(2)), done=lidx(S(2), 'big1.bin 在 upperdir'), mark=lidx(S(2), 'upperdir 里的文件'), kv=KV([['big1.bin', '134217731 字节,整个文件'], ['big2.bin(只 chmod)', '134217728 字节,整个文件'], ['small.txt', '1025 字节']], ['big2.bin(只 chmod)'])),
    step("把大文件放进 volume(先 cp 进去),再往它追加 1 字节:0.0 ms。volume 不在镜像的层里,没有 copy-up;这个对比只说明数据在 volume 里时追加不用复制,没有测 volume 本身的读写速度。", t=tl(S(3)), done=lidx(S(3), 'volume 里的 big1.bin'), kv=KV([['镜像层里的大文件', '第 1 次写要整个复制'], ['volume 里的大文件', '追加 0.0 ms']], ['volume 里的大文件'])),
]
A = mkartc('c20', 20, 'Docker,OverlayFS,copy-up,写时复制,容器性能,真实验证,动画演示',
    '在 Docker Desktop 里实测 OverlayFS 的 copy-up:镜像里 128 MiB 的文件,容器里第一次追加 1 字节要 155.0~2174.1 ms(3 次),之后追加约 0 ms;只 chmod 也要 179.6~862.0 ms;upperdir 里是整个文件的拷贝;放在 volume 里的同样文件追加 0.0 ms。',
    '容器改动镜像里的一个大文件,第一次写入为什么会卡一下?这篇用 128 MiB 的文件实测 copy-up:读、追加、只改权限各要多久,upperdir 里多了什么,以及数据放在 volume 里有什么不同。',
    [('155.0~2174.1 ms', '第 1 次往镜像里 128 MiB 文件追加 1 字节的耗时范围(3 次),第 2 次起约 0 ms'), ('chmod 也要复制', '只改权限也让 128 MiB 的文件整个复制进 upperdir(179.6~862.0 ms)'), ('0.0 ms', '同样的文件在 volume 里追加 1 字节')],
    [('第一次写', '<p>读文件不会触发复制(0.1 ms)。第一次往 128 MiB 的文件追加 1 字节,三个新容器分别花了 2174.1、242.7、155.0 ms;随后再追加只要约 0 ms。三次数字差别很大,这台机器上同时还跑着别的容器,我没有隔离干扰,所以别把某个绝对值当成基准,看量级和“只有第一次慢”这个现象。</p><p>只对 big2.bin 做 <code>chmod</code>,也要 179.6~862.0 ms;往 1 KB 的小文件追加只要几毫秒。这个版本的 overlay 在元数据改动时也复制整个文件(见 upperdir 里 big2.bin 是完整的 134217728 字节);是否有 metacopy 之类的选项能避免,我没有测。</p>'),
     ('upperdir 里是什么', '<p>big1.bin 的大小是 134217731 字节,整个文件都在 upperdir 里;改动 1 字节占用了 128 MiB 的可写层空间。镜像里有大文件又要频繁改的程序(比如数据库文件)不要放在镜像层里。</p>'),
     ('用 volume', '<p>把大文件放在 volume 里,追加 1 字节是 0.0 ms,因为 volume 不是镜像的层。这个对比没有测 volume 的读写吞吐,只说明没有 copy-up。</p>')],
    steps,
    [ENV_C + '。基础镜像 python:3.12-alpine,脚本用 time.perf_counter 在容器内计时;每个场景用 3 个新容器各测一次并列出全部数值(没有取平均);文件内容是 os.urandom 随机数据;机器上同时有其它容器在运行,数字抖动大;实验后已删除镜像、容器和 volume',
     '没有验证:经典 overlay2 驱动、metacopy 选项、更大的文件(GB 级)、volume 的真实吞吐、reflink / 其它文件系统的行为、目录 rename 的代价'],
    'copy-up 的代价')
